/// The `KosherError` error domain of module `kosher`: catch it to handle any of
/// its codes, or a subclass for one code.
sealed class KosherException extends NativeException {
  /// Creates a domain error carrying [code] and [message].
  KosherException(super.code, super.message);
}

/// The latitude is not between -90 and 90 degrees.
final class InvalidLatitudeException extends KosherException {
  /// Creates an [InvalidLatitudeException] (code 1).
  InvalidLatitudeException([String message = 'The latitude is not between -90 and 90 degrees.']) : super(1, message);
}

/// The longitude is not between -180 and 180 degrees.
final class InvalidLongitudeException extends KosherException {
  /// Creates an [InvalidLongitudeException] (code 2).
  InvalidLongitudeException([String message = 'The longitude is not between -180 and 180 degrees.']) : super(2, message);
}

/// An elevation is negative or not a finite number.
final class InvalidElevationException extends KosherException {
  /// Creates an [InvalidElevationException] (code 3).
  InvalidElevationException([String message = 'An elevation is negative or not a finite number.']) : super(3, message);
}

/// The date does not exist, or is outside the supported range.
final class InvalidDateException extends KosherException {
  /// Creates an [InvalidDateException] (code 4).
  InvalidDateException([String message = 'The date does not exist, or is outside the supported range.']) : super(4, message);
}

/// The time needs a time zone and none was given: the Kiddush Levana times, and any time
/// more than 150 degrees from Greenwich.
final class TimeZoneRequiredException extends KosherException {
  /// Creates a [TimeZoneRequiredException] (code 5).
  TimeZoneRequiredException([String message = 'The time needs a time zone and none was given: the Kiddush Levana times, and any time']) : super(5, message);
}

/// The time zone callback failed, or gave an offset of a day or more.
final class TimeZoneCallbackFailedException extends KosherException {
  /// Creates a [TimeZoneCallbackFailedException] (code 6).
  TimeZoneCallbackFailedException([String message = 'The time zone callback failed, or gave an offset of a day or more.']) : super(6, message);
}

/// The sun stays above the angle the time needs all day, as in the far north in summer.
final class AllDayException extends KosherException {
  /// Creates an [AllDayException] (code 10).
  AllDayException([String message = 'The sun stays above the angle the time needs all day, as in the far north in summer.']) : super(10, message);
}

/// The sun stays below the angle the time needs all day, as in the far north in winter.
final class AllNightException extends KosherException {
  /// Creates an [AllNightException] (code 11).
  AllNightException([String message = 'The sun stays below the angle the time needs all day, as in the far north in winter.']) : super(11, message);
}

/// The time only exists on certain dates, and this is not one.
final class NotApplicableException extends KosherException {
  /// Creates a [NotApplicableException] (code 12).
  NotApplicableException([String message = 'The time only exists on certain dates, and this is not one.']) : super(12, message);
}

/// A calculation failed in a way that should not happen; please report the location and
/// date.
final class InternalException extends KosherException {
  /// Creates an [InternalException] (code 13).
  InternalException([String message = 'A calculation failed in a way that should not happen; please report the location and']) : super(13, message);
}

NativeException _mapKosherException(int code, String message, Uint8List payload) {
  switch (code) {
    case 1:
      return InvalidLatitudeException(message);
    case 2:
      return InvalidLongitudeException(message);
    case 3:
      return InvalidElevationException(message);
    case 4:
      return InvalidDateException(message);
    case 5:
      return TimeZoneRequiredException(message);
    case 6:
      return TimeZoneCallbackFailedException(message);
    case 10:
      return AllDayException(message);
    case 11:
      return AllNightException(message);
    case 12:
      return NotApplicableException(message);
    case 13:
      return InternalException(message);
    default:
      return _runtimeException(code, message, payload);
  }
}

/// A day on the Gregorian calendar.
final class GregorianDate {
  /// Creates a [GregorianDate].
  GregorianDate({required this.year, required this.month, required this.day});

  /// The year, for example 2024.
  final int year;
  /// The month, 1 to 12.
  final int month;
  /// The day of the month, from 1.
  final int day;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is GregorianDate &&
      year == other.year &&
      month == other.month &&
      day == other.day;

  @override
  int get hashCode => Object.hashAll([GregorianDate, year, month, day]);

  @override
  String toString() => 'GregorianDate(year: $year, month: $month, day: $day)';
}

void _packGregorianDate(_BufferWriter w, GregorianDate v) {
  w.writeI32(v.year);
  w.writeI32(v.month);
  w.writeI32(v.day);
}

GregorianDate _unpackGregorianDate(_BufferReader r) => GregorianDate(
      year: r.readI32(),
      month: r.readI32(),
      day: r.readI32(),
    );

/// A place on earth: where to calculate *zmanim* for. Heights are in meters above sea level;
/// leave them 0 for sea level.
///
/// The time zone is not part of the location: pass a
/// `TimeZoneOffset` to `Zmanim` and
/// `MyZmanim`.
final class Location {
  /// Creates a [Location].
  Location({required this.latitude, required this.longitude, required this.elevation, required this.easternHorizonElevation, required this.westernHorizonElevation});

  /// Latitude in degrees, north positive.
  final double latitude;
  /// Longitude in degrees, east positive.
  final double longitude;
  /// The observer's height. Elevation makes sunrise earlier and sunset later.
  final double elevation;
  /// The height of the eastern horizon, over which the sun rises.
  final double easternHorizonElevation;
  /// The height of the western horizon, behind which the sun sets.
  final double westernHorizonElevation;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Location &&
      latitude == other.latitude &&
      longitude == other.longitude &&
      elevation == other.elevation &&
      easternHorizonElevation == other.easternHorizonElevation &&
      westernHorizonElevation == other.westernHorizonElevation;

  @override
  int get hashCode => Object.hashAll([Location, latitude, longitude, elevation, easternHorizonElevation, westernHorizonElevation]);

  @override
  String toString() => 'Location(latitude: $latitude, longitude: $longitude, elevation: $elevation, easternHorizonElevation: $easternHorizonElevation, westernHorizonElevation: $westernHorizonElevation)';
}

void _packLocation(_BufferWriter w, Location v) {
  w.writeF64(v.latitude);
  w.writeF64(v.longitude);
  w.writeF64(v.elevation);
  w.writeF64(v.easternHorizonElevation);
  w.writeF64(v.westernHorizonElevation);
}

Location _unpackLocation(_BufferReader r) => Location(
      latitude: r.readF64(),
      longitude: r.readF64(),
      elevation: r.readF64(),
      easternHorizonElevation: r.readF64(),
      westernHorizonElevation: r.readF64(),
    );

final _kosherRustBindingsKosherSeaLevelLocation = _lib.lookupFunction<
    Pointer<Uint8> Function(Double, Double, Pointer<Size>, Pointer<_Error>),
    Pointer<Uint8> Function(double, double, Pointer<Size>, Pointer<_Error>)>('kosher_rust_bindings_kosher_sea_level_location');

/// A location at sea level, with flat horizons.
Location seaLevelLocation(double latitude, double longitude) {
  final _result = _kosherRustBindingsKosherSeaLevelLocation(latitude, longitude, _outLen, _err);
  _check(_err);
  return _decode(_takeBytes(_result, _outLen.value), _unpackLocation);
}

final _kosherRustBindingsKosherValidateLocation = _lib.lookupFunction<
    Void Function(Pointer<Uint8>, Size, Bool, Pointer<_Error>),
    void Function(Pointer<Uint8>, int, bool, Pointer<_Error>)>('kosher_rust_bindings_kosher_validate_location');

/// Checks a location the way `Zmanim` will.
///
/// # Errors
///
/// `KosherError::InvalidLatitude`, `KosherError::InvalidLongitude` or
/// `KosherError::InvalidElevation`; `KosherError::TimeZoneRequired` beyond 150 degrees
/// from Greenwich when `has_time_zone` is false.
///
/// Throws [KosherException] on domain errors.
void validateLocation(Location location, bool hasTimeZone) {
  final _arena = Arena();
  try {
    final _locationBytes = _encode(location, _packLocation);
    _kosherRustBindingsKosherValidateLocation(_stage(_arena, _locationBytes), _locationBytes.length, hasTimeZone, _err);
    _check(_err, _mapKosherException);
  } finally {
    _arena.releaseAll();
  }
}

/// Where the calendar is kept. Outside Israel, Yom Tov has a second day.
enum Region {
  /// Eretz Yisrael: one day of Yom Tov.
  israel(0),
  /// Everywhere else: two days of Yom Tov.
  diaspora(1);

  const Region(this.value);

  /// The C discriminant.
  final int value;

  /// The variant whose discriminant is [value].
  static Region fromValue(int value) => values.firstWhere(
      (e) => e.value == value,
      orElse: () => throw ArgumentError.value(value, 'value', 'not a Region discriminant'));
}

/// A month of the Hebrew calendar, numbered from Tishrei. A leap year has two Adars:
