enum HebrewMonth {
  /// Tishrei.
  tishrei(1),
  /// Cheshvan.
  cheshvan(2),
  /// Kislev.
  kislev(3),
  /// Teves.
  teves(4),
  /// Shevat.
  shevat(5),
  /// Adar I, only in a leap year.
  adarI(6),
  /// Adar, or Adar II in a leap year.
  adar(7),
  /// Nisan.
  nisan(8),
  /// Iyar.
  iyar(9),
  /// Sivan.
  sivan(10),
  /// Tammuz.
  tammuz(11),
  /// Av.
  av(12),
  /// Elul.
  elul(13);

  const HebrewMonth(this.value);

  /// The C discriminant.
  final int value;

  /// The variant whose discriminant is [value].
  static HebrewMonth fromValue(int value) => values.firstWhere(
      (e) => e.value == value,
      orElse: () => throw ArgumentError.value(value, 'value', 'not a HebrewMonth discriminant'));
}

