/// Whether Cheshvan and Kislev are long or short in a year.
enum YearLength {
  /// Deficient: Cheshvan and Kislev both have 29 days (353 or 383 days).
  chaserim(0),
  /// Regular: Cheshvan has 29 days and Kislev 30 (354 or 384 days).
  kesidran(1),
  /// Complete: Cheshvan and Kislev both have 30 days (355 or 385 days).
  shelaimim(2);

  const YearLength(this.value);

  /// The C discriminant.
  final int value;

  /// The variant whose discriminant is [value].
  static YearLength fromValue(int value) => values.firstWhere(
      (e) => e.value == value,
      orElse: () => throw ArgumentError.value(value, 'value', 'not a YearLength discriminant'));
}

