/// What kind of time a `Zman` is.
enum Category {
  /// Start and end of astronomical, civil and nautical twilight.
  twilight(0),
  /// Dawn (*alos*).
  alos(1),
  /// Earliest time for tallis and tefillin (*misheyakir*).
  misheyakir(2),
  /// Sunrise (*netz*).
  netz(3),
  /// Latest time for the morning Shema.
  sofZmanShma(4),
  /// Latest time for the morning prayer.
  sofZmanTefila(5),
  /// Latest time to eat chametz on Erev Pesach.
  sofZmanAchilasChametz(6),
  /// Latest time to burn chametz on Erev Pesach.
  sofZmanBiurChametz(7),
  /// Midday (*chatzos hayom*).
  chatzosHayom(8),
  /// Earliest Mincha (*mincha gedola*).
  minchaGedola(9),
  /// *Plag hamincha*.
  plagHamincha(10),
  /// Shortly before *mincha ketana*.
  samuchLeMinchaKetana(11),
  /// Preferred Mincha time (*mincha ketana*).
  minchaKetana(12),
  /// Twilight between sunset and nightfall (*bein hashmashos*).
  beinHashmashos(13),
  /// Candle lighting before Shabbos or Yom Tov.
  candleLighting(14),
  /// Sunset (*shkiya*).
  shkiya(15),
  /// Nightfall (*tzais*).
  tzais(16),
  /// The window for Kiddush Levana.
  kidushLevana(17),
  /// Midnight (*chatzos halayla*).
  chatzosHalayla(18);

  const Category(this.value);

  /// The C discriminant.
  final int value;

  /// The variant whose discriminant is [value].
  static Category fromValue(int value) => values.firstWhere(
      (e) => e.value == value,
      orElse: () => throw ArgumentError.value(value, 'value', 'not a Category discriminant'));
}

/// The solar position algorithm.
enum Calculator {
  /// The NOAA algorithm, KosherJava's default. Good to about a minute.
  noaa(0),
  /// Jean Meeus's higher-accuracy VSOP87 algorithm.
  meeus(1),
  /// The NREL Solar Position Algorithm, solved on the topocentric zenith.
  spa(2);

  const Calculator(this.value);

  /// The C discriminant.
  final int value;

  /// The variant whose discriminant is [value].
  static Calculator fromValue(int value) => values.firstWhere(
      (e) => e.value == value,
      orElse: () => throw ArgumentError.value(value, 'value', 'not a Calculator discriminant'));
}

/// Why a time in `ZmanTime` could not be calculated.
enum ZmanFailure {
  /// The sun stays above the angle the time needs all day.
  allDay(0),
  /// The sun stays below the angle the time needs all day.
  allNight(1),
  /// The time does not apply on this date.
  notApplicable(2),
  /// The time needs a time zone and none was given.
  timeZoneRequired(3),
  /// The time zone callback failed.
  timeZoneCallbackFailed(4),
  /// An internal calculation error.
  internal(5);

  const ZmanFailure(this.value);

  /// The C discriminant.
  final int value;

  /// The variant whose discriminant is [value].
  static ZmanFailure fromValue(int value) => values.firstWhere(
      (e) => e.value == value,
      orElse: () => throw ArgumentError.value(value, 'value', 'not a ZmanFailure discriminant'));
}

/// How `Zmanim` calculates. `default_config` matches KosherJava's defaults.
final class Config {
  /// Creates a [Config].
  Config({required this.candleLightingMinutes, required this.useAstronomicalChatzosForOtherZmanim, required this.useElevation, required this.ateretTorahSunsetMinutes, required this.useAstronomicalChatzos, required this.calculator, required this.applyDeltaT});

  /// How long before sea-level sunset candle lighting is, in minutes. Default 18.
  final int candleLightingMinutes;
  /// Whether proportional zmanim divide the day at astronomical *chatzos*. Default false.
  final bool useAstronomicalChatzosForOtherZmanim;
  /// Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
  /// and sunset themselves. Default false.
  final bool useElevation;
  /// How long after sunset Tzais Ateret Torah is, in minutes. Default 40.
  final int ateretTorahSunsetMinutes;
  /// Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
  /// sunset. Default true.
  final bool useAstronomicalChatzos;
  /// The solar position algorithm. Default NOAA.
  final Calculator calculator;
  /// For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true.
  final bool applyDeltaT;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Config &&
      candleLightingMinutes == other.candleLightingMinutes &&
      useAstronomicalChatzosForOtherZmanim == other.useAstronomicalChatzosForOtherZmanim &&
      useElevation == other.useElevation &&
      ateretTorahSunsetMinutes == other.ateretTorahSunsetMinutes &&
      useAstronomicalChatzos == other.useAstronomicalChatzos &&
      calculator == other.calculator &&
      applyDeltaT == other.applyDeltaT;

  @override
  int get hashCode => Object.hashAll([Config, candleLightingMinutes, useAstronomicalChatzosForOtherZmanim, useElevation, ateretTorahSunsetMinutes, useAstronomicalChatzos, calculator, applyDeltaT]);

  @override
  String toString() => 'Config(candleLightingMinutes: $candleLightingMinutes, useAstronomicalChatzosForOtherZmanim: $useAstronomicalChatzosForOtherZmanim, useElevation: $useElevation, ateretTorahSunsetMinutes: $ateretTorahSunsetMinutes, useAstronomicalChatzos: $useAstronomicalChatzos, calculator: $calculator, applyDeltaT: $applyDeltaT)';
}

void _packConfig(_BufferWriter w, Config v) {
  w.writeI32(v.candleLightingMinutes);
  w.writeBool(v.useAstronomicalChatzosForOtherZmanim);
  w.writeBool(v.useElevation);
  w.writeI32(v.ateretTorahSunsetMinutes);
  w.writeBool(v.useAstronomicalChatzos);
  w.writeI32(v.calculator.value);
  w.writeBool(v.applyDeltaT);
}

Config _unpackConfig(_BufferReader r) => Config(
      candleLightingMinutes: r.readI32(),
      useAstronomicalChatzosForOtherZmanim: r.readBool(),
      useElevation: r.readBool(),
      ateretTorahSunsetMinutes: r.readI32(),
      useAstronomicalChatzos: r.readBool(),
      calculator: Calculator.fromValue(r.readI32()),
      applyDeltaT: r.readBool(),
    );

/// One zman's time, or why it has none.
final class ZmanTime {
  /// Creates a [ZmanTime].
  ZmanTime({required this.zman, this.time, this.failure});

  /// The zman.
  final Zman zman;
  /// The time in Unix milliseconds, when it could be calculated.
  final int? time;
  /// Why it could not, when it could not.
  final ZmanFailure? failure;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ZmanTime &&
      zman == other.zman &&
      time == other.time &&
      failure == other.failure;

  @override
  int get hashCode => Object.hashAll([ZmanTime, zman, time, failure]);

  @override
  String toString() => 'ZmanTime(zman: $zman, time: $time, failure: $failure)';
}

void _packZmanTime(_BufferWriter w, ZmanTime v) {
  w.writeI32(v.zman.value);
  _packOptionalOfI64(w, v.time);
  _packOptionalOfZmanFailure(w, v.failure);
}

ZmanTime _unpackZmanTime(_BufferReader r) => ZmanTime(
      zman: Zman.fromValue(r.readI32()),
      time: _unpackOptionalOfI64(r),
      failure: _unpackOptionalOfZmanFailure(r),
    );

/// The time zone, supplied by the caller: the offset from UTC at an instant.
///
/// Only the Kiddush Levana times, and places more than 150 degrees from Greenwich, need
/// one. It is called synchronously, possibly several times per calculation.
///
/// A callback interface: implement it and pass an instance to any
/// function taking a [TimeZoneOffset]. The library keeps the instance alive
/// until the producer releases it.
///
/// Methods that return a value run synchronously and must be called by
/// the producer on this isolate's thread during a call from Dart; a
/// thrown exception fails that call with [NativeException.foreignCode]
/// (or, from a method that throws, the domain exception's code and
/// fields). Void methods may be called from any thread: they're
/// delivered asynchronously on this isolate's event loop, in the zone
/// that passed the instance, where a thrown exception is an uncaught
/// error of that zone. Object arguments are owned by the
/// implementation.
abstract class TimeZoneOffset {
  /// The offset from UTC, in seconds east, in effect at `unix_seconds`.
  ///
  /// # Errors
  ///
  /// Fail when the offset is unknown; the calculation then reports
  /// `KosherError::TimeZoneCallbackFailed`.
  int offsetSeconds(int unixSeconds);
}

typedef _KosherRustBindingsKosherZmanimTimeZoneOffsetOffsetSeconds = Int32 Function(Pointer<Void>, Int64, Pointer<_Error>);

// The C `kosher_rust_bindings_kosher_zmanim_TimeZoneOffset_vtable` layout.
final class _TimeZoneOffsetVtable extends Struct {
  @Uint32()
  external int size;
  @Uint32()
  external int flags;
  external Pointer<NativeFunction<Void Function(Pointer<Void>)>> free;
  external Pointer<NativeFunction<_KosherRustBindingsKosherZmanimTimeZoneOffsetOffsetSeconds>> offsetSeconds;
}

// Vtable entry `kosher_rust_bindings_kosher_zmanim_TimeZoneOffset_vtable.offset_seconds`.
int _timeZoneOffsetOffsetSeconds(Pointer<Void> ctx, int unixSeconds, Pointer<_Error> outErr) {
  try {
    return (_callbackTarget(ctx) as TimeZoneOffset).offsetSeconds(unixSeconds);
  } catch (e) {
    _foreignError(outErr, e);
  }
  return 0;
}

void _timeZoneOffsetDispatch(Object impl, int method, List<Object?> message) {
  // Every TimeZoneOffset method returns a value: nothing is forwarded.
}

final Pointer<_TimeZoneOffsetVtable> _timeZoneOffsetVtable = () {
  final vtable = calloc<_TimeZoneOffsetVtable>();
  vtable.ref
      ..size = sizeOf<_TimeZoneOffsetVtable>()
      ..flags = 0
      ..free = _callbackFree
      ..offsetSeconds = _pin(NativeCallable<_KosherRustBindingsKosherZmanimTimeZoneOffsetOffsetSeconds>.isolateLocal(_timeZoneOffsetOffsetSeconds, exceptionalReturn: 0));
