/// A day's portion of Tehillim.
sealed class TehillimUnit {
  const TehillimUnit();
}

/// Whole chapters, `start` to `end` inclusive.
final class TehillimUnitPsalms extends TehillimUnit {
  /// Creates a [TehillimUnitPsalms].
  TehillimUnitPsalms(this.start, this.end);

  /// The first chapter.
  final int start;
  /// The last chapter.
  final int end;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TehillimUnitPsalms &&
      start == other.start &&
      end == other.end;

  @override
