  @override
  String toString() => 'TehillimUnitPsalms(start: $start, end: $end)';
}

/// Part of one long chapter (119, split over two days).
final class TehillimUnitPsalmVerses extends TehillimUnit {
  /// Creates a [TehillimUnitPsalmVerses].
  TehillimUnitPsalmVerses(this.psalm, this.startVerse, this.endVerse);

  /// The chapter.
  final int psalm;
  /// The first verse.
  final int startVerse;
  /// The last verse.
  final int endVerse;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TehillimUnitPsalmVerses &&
      psalm == other.psalm &&
      startVerse == other.startVerse &&
      endVerse == other.endVerse;

  @override
  int get hashCode => Object.hashAll([TehillimUnitPsalmVerses, psalm, startVerse, endVerse]);

  @override
  String toString() => 'TehillimUnitPsalmVerses(psalm: $psalm, startVerse: $startVerse, endVerse: $endVerse)';
}

